const express = require('express');
const http = require('http');
const { Server } = require('socket.io');
const multer = require('multer');
const path = require('path');
const fs = require('fs');
const crypto = require('crypto');

const app = express();
const server = http.createServer(app);
const io = new Server(server, {
  maxHttpBufferSize: 1e9 // 1GB limit for websocket buffer
});

const PORT = process.env.PORT || 3000;
const DATA_DIR = path.join(__dirname, 'data');
const UPLOAD_DIR = path.join(__dirname, 'uploads');
const CONFIG_PATH = path.join(__dirname, 'config.json');
const MESSAGES_FILE = path.join(DATA_DIR, 'messages.json');

if (!fs.existsSync(DATA_DIR)) fs.mkdirSync(DATA_DIR, { recursive: true });
if (!fs.existsSync(UPLOAD_DIR)) fs.mkdirSync(UPLOAD_DIR, { recursive: true });

// Embedded frontend fallback for Render/Cloud (Works even if public folder is missing)
const B64_HTML = "";
const B64_CSS = "";
const B64_JS = "";

const FALLBACK_HTML = Buffer.from(B64_HTML, 'base64').toString('utf8');
const FALLBACK_CSS = Buffer.from(B64_CSS, 'base64').toString('utf8');
const FALLBACK_JS = Buffer.from(B64_JS, 'base64').toString('utf8');

let config = {
  roomPasscode: '3667',
  adminPasscode: '2412',
  geminiApiKey: process.env.GEMINI_API_KEY || 'AQ.Ab8RN6LjNDwbKcf-Jhu__vzPsyG3pwHAjhpJAL80yNPPOmcw6w'
};

function loadConfig() {
  try {
    if (fs.existsSync(CONFIG_PATH)) {
      const raw = fs.readFileSync(CONFIG_PATH, 'utf8');
      config = { ...config, ...JSON.parse(raw) };
    }
  } catch (err) {}
}
loadConfig();

function saveConfig() {
  try {
    fs.writeFileSync(CONFIG_PATH, JSON.stringify(config, null, 2), 'utf8');
  } catch (err) {}
}

let messages = [];
try {
  if (fs.existsSync(MESSAGES_FILE)) {
    const raw = fs.readFileSync(MESSAGES_FILE, 'utf8');
    messages = JSON.parse(raw);
    if (!Array.isArray(messages)) messages = [];
  }
} catch (err) {
  messages = [];
}

function saveMessages() {
  try {
    fs.writeFileSync(MESSAGES_FILE, JSON.stringify(messages.slice(-200), null, 2), 'utf8');
  } catch (err) {}
}

// Rate limiting tracker to prevent brute-force passcode guessing
const failedAttempts = new Map();

function checkRateLimit(ip) {
  const now = Date.now();
  const record = failedAttempts.get(ip);
  if (!record) return { allowed: true };
  if (record.lockedUntil && now < record.lockedUntil) {
    const waitSeconds = Math.ceil((record.lockedUntil - now) / 1000);
    return { allowed: false, waitSeconds };
  }
  if (record.lockedUntil && now >= record.lockedUntil) {
    failedAttempts.delete(ip);
    return { allowed: true };
  }
  return { allowed: true };
}

function recordFailedAttempt(ip) {
  const now = Date.now();
  const record = failedAttempts.get(ip) || { count: 0, lockedUntil: 0 };
  record.count += 1;
  if (record.count >= 5) {
    record.lockedUntil = now + (5 * 60 * 1000); // Lock for 5 mins
  }
  failedAttempts.set(ip, record);
}

function clearFailedAttempts(ip) {
  failedAttempts.delete(ip);
}

// Escape HTML server-side to neutralize XSS
function sanitizeText(str) {
  if (typeof str !== 'string') return '';
  return str
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

const storage = multer.diskStorage({
  destination: (req, file, cb) => cb(null, UPLOAD_DIR),
  filename: (req, file, cb) => {
    const ext = path.extname(file.originalname).toLowerCase().slice(0, 10);
    const unique = Date.now() + '-' + crypto.randomBytes(8).toString('hex');
    cb(null, unique + ext);
  }
});

// Strict 1GB file size limit enforced at Multer backend
const ONE_GB = 1024 * 1024 * 1024; // 1,073,741,824 bytes

const upload = multer({
  storage: storage,
  limits: { fileSize: ONE_GB }
});

app.use(express.json());
app.use('/uploads', express.static(UPLOAD_DIR));
app.use(express.static(path.join(__dirname, 'public')));
app.use(express.static(__dirname));

// Guaranteed web routes
app.get('/', (req, res) => {
  const p = path.join(__dirname, 'public', 'index.html');
  if (fs.existsSync(p)) return res.sendFile(p);
  const p2 = path.join(__dirname, 'index.html');
  if (fs.existsSync(p2)) return res.sendFile(p2);
  res.setHeader('Content-Type', 'text/html; charset=utf-8');
  res.send(FALLBACK_HTML);
});

app.get(['/style.css', '/css/style.css'], (req, res) => {
  const p = path.join(__dirname, 'public', 'css', 'style.css');
  if (fs.existsSync(p)) return res.sendFile(p);
  const p2 = path.join(__dirname, 'style.css');
  if (fs.existsSync(p2)) return res.sendFile(p2);
  res.setHeader('Content-Type', 'text/css; charset=utf-8');
  res.send(FALLBACK_CSS);
});

app.get(['/app.js', '/js/app.js'], (req, res) => {
  const p = path.join(__dirname, 'public', 'js', 'app.js');
  if (fs.existsSync(p)) return res.sendFile(p);
  const p2 = path.join(__dirname, 'app.js');
  if (fs.existsSync(p2)) return res.sendFile(p2);
  res.setHeader('Content-Type', 'application/javascript; charset=utf-8');
  res.send(FALLBACK_JS);
});

app.post('/api/upload', (req, res) => {
  upload.single('file')(req, res, (err) => {
    if (err instanceof multer.MulterError) {
      if (err.code === 'LIMIT_FILE_SIZE') {
        return res.status(400).json({ error: 'T?p qu? l?n! Gi?i h?n dung l??ng t?i ?a l? 1GB.' });
      }
      return res.status(400).json({ error: 'L?i t?i t?p: ' + err.message });
    } else if (err) {
      return res.status(500).json({ error: 'L?i m?y ch? khi t?i t?p: ' + err.message });
    }

    if (!req.file) {
      return res.status(400).json({ error: 'Kh?ng t?m th?y t?p t?i l?n' });
    }

    const originalName = sanitizeText(Buffer.from(req.file.originalname, 'latin1').toString('utf8'));
    const fileData = {
      originalName: originalName,
      fileName: req.file.filename,
      fileSize: req.file.size,
      mimeType: req.file.mimetype,
      url: '/uploads/' + req.file.filename
    };

    res.json({ success: true, file: fileData });
  });
});

app.get('/api/status', (req, res) => {
  res.json({
    hasGeminiKey: !!config.geminiApiKey,
    roomName: 'Khu t? tr? Noel Nguy?n'
  });
});

async function callGemini(promptText) {
  const apiKey = (config.geminiApiKey || process.env.GEMINI_API_KEY || '').trim();
  if (!apiKey) {
    return '?? Bot AI ch?a ???c c?u h?nh GEMINI_API_KEY! Nh?n n?t ?? Bot AI ?? nh?p key.';
  }

  const endpoint = 'https://generativelanguage.googleapis.com/v1beta/models/gemini-flash-latest:generateContent?key=' + encodeURIComponent(apiKey);
  const requestBody = {
    contents: [
      {
        parts: [
          {
            text: 'B?n l? "Noel Bot AI" ?? - tr? l? ?o vui t?nh, th?n thi?n, th?ng minh c?a nh?m chat "Khu t? tr? Noel Nguy?n". H?y tr? l?i ng?n g?n, t? nhi?n b?ng ti?ng Vi?t.\n\nC?u h?i: ' + promptText
          }
        ]
      }
    ],
    generationConfig: {
      temperature: 0.7,
      maxOutputTokens: 1000
    }
  };

  try {
    const res = await fetch(endpoint, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(requestBody)
    });

    if (!res.ok) {
      const errJson = await res.json().catch(() => ({}));
      return '? L?i k?t n?i Gemini API (' + res.status + '): ' + (errJson?.error?.message || 'Kh?ng th? t?o ph?n h?i');
    }

    const data = await res.json();
    const reply = data?.candidates?.[0]?.content?.parts?.[0]?.text;
    return reply ? reply.trim() : '?? Bot kh?ng nh?n ???c ph?n h?i t? AI.';
  } catch (err) {
    return '? Kh?ng th? k?t n?i t?i Google Gemini. Vui l?ng th? l?i sau.';
  }
}

const onlineUsers = new Map();
const adminTokens = new Set();

io.on('connection', (socket) => {
  let currentUser = null;
  const clientIp = socket.handshake.headers['x-forwarded-for'] || socket.handshake.address || 'unknown_ip';

  socket.on('join_room', ({ username, passcode }) => {
    const limitCheck = checkRateLimit(clientIp);
    if (!limitCheck.allowed) {
      return socket.emit('join_error', '?? B?n ?? nh?p sai qu? nhi?u l?n. Vui l?ng ??i ' + limitCheck.waitSeconds + ' gi?y r?i th? l?i!');
    }

    if (!username || typeof username !== 'string' || !username.trim()) {
      return socket.emit('join_error', 'Vui l?ng nh?p t?n ng??i d?ng h?p l?.');
    }

    if (passcode !== config.roomPasscode) {
      recordFailedAttempt(clientIp);
      return socket.emit('join_error', 'M?t kh?u ph?ng kh?ng ch?nh x?c!');
    }

    clearFailedAttempts(clientIp);

    const safeUsername = sanitizeText(username.trim()).slice(0, 25);
    currentUser = {
      username: safeUsername,
      isAdmin: false,
      socketId: socket.id,
      joinedAt: Date.now()
    };

    onlineUsers.set(socket.id, currentUser);
    socket.join('noel_autonomous_room');

    socket.emit('join_success', {
      user: currentUser,
      roomName: 'Khu t? tr? Noel Nguy?n',
      history: messages.slice(-150),
      onlineUsers: Array.from(onlineUsers.values()),
      hasGeminiKey: !!config.geminiApiKey
    });

    io.to('noel_autonomous_room').emit('user_joined', {
      user: currentUser,
      onlineUsers: Array.from(onlineUsers.values())
    });
  });

  socket.on('verify_admin', ({ passcode }) => {
    const limitCheck = checkRateLimit(clientIp + '_admin');
    if (!limitCheck.allowed) {
      return socket.emit('admin_error', '?? ?? nh?p sai m? Admin qu? nhi?u l?n. Cooldown: ' + limitCheck.waitSeconds + ' gi?y!');
    }

    if (passcode === config.adminPasscode) {
      clearFailedAttempts(clientIp + '_admin');
      const adminToken = crypto.randomBytes(32).toString('hex');
      adminTokens.add(adminToken);

      if (currentUser) {
        currentUser.isAdmin = true;
        onlineUsers.set(socket.id, currentUser);
      }

      socket.emit('admin_success', { token: adminToken });
      io.to('noel_autonomous_room').emit('user_role_changed', {
        socketId: socket.id,
        username: currentUser ? currentUser.username : 'Unknown',
        isAdmin: true,
        onlineUsers: Array.from(onlineUsers.values())
      });
    } else {
      recordFailedAttempt(clientIp + '_admin');
      socket.emit('admin_error', 'M?t kh?u qu?n tr? vi?n kh?ng ch?nh x?c!');
    }
  });

  socket.on('resume_admin', ({ adminToken }) => {
    if (adminToken && typeof adminToken === 'string' && adminTokens.has(adminToken)) {
      if (currentUser) {
        currentUser.isAdmin = true;
        onlineUsers.set(socket.id, currentUser);
      }
      socket.emit('admin_success', { token: adminToken });
      io.to('noel_autonomous_room').emit('user_role_changed', {
        socketId: socket.id,
        username: currentUser ? currentUser.username : 'Unknown',
        isAdmin: true,
        onlineUsers: Array.from(onlineUsers.values())
      });
    }
  });

  socket.on('update_gemini_key', ({ apiKey }) => {
    if (!apiKey || typeof apiKey !== 'string') return;
    config.geminiApiKey = apiKey.trim();
    saveConfig();
    socket.emit('gemini_key_updated', { success: true });
    io.to('noel_autonomous_room').emit('bot_status_changed', { hasGeminiKey: true });
  });

  socket.on('send_message', async ({ text, file, adminToken }) => {
    if (!currentUser) return;

    const isLegitAdmin = !!(adminToken && adminTokens.has(adminToken));
    const hasAdminRole = currentUser.isAdmin && isLegitAdmin;
    const cleanText = sanitizeText((text || '').trim()).slice(0, 2000);

    if (!cleanText && !file) return;

    const messageObj = {
      id: 'msg_' + Date.now() + '_' + crypto.randomBytes(4).toString('hex'),
      username: currentUser.username,
      isAdmin: hasAdminRole,
      isBot: false,
      text: cleanText,
      file: file || null,
      timestamp: new Date().toLocaleTimeString('vi-VN', { hour: '2-digit', minute: '2-digit' }),
      createdAt: Date.now()
    };

    messages.push(messageObj);
    if (messages.length > 250) messages.shift();
    saveMessages();

    io.to('noel_autonomous_room').emit('new_message', messageObj);

    const botTriggers = ['@bot', '@ai', '@gemini', '/ai', '/ask', 'noel bot'];
    const lowerText = cleanText.toLowerCase();
    const isBotRequested = botTriggers.some(trigger => lowerText.includes(trigger));

    if (isBotRequested) {
      let botPrompt = cleanText;
      botTriggers.forEach(t => {
        const regex = new RegExp(t, 'gi');
        botPrompt = botPrompt.replace(regex, '');
      });
      botPrompt = botPrompt.trim() || 'Ch?o b?n Noel Bot!';

      io.to('noel_autonomous_room').emit('bot_typing', { isTyping: true });

      try {
        const aiAnswer = await callGemini(botPrompt);
        const botMessage = {
          id: 'bot_' + Date.now() + '_' + crypto.randomBytes(4).toString('hex'),
          username: 'Noel Bot AI',
          isAdmin: false,
          isBot: true,
          text: sanitizeText(aiAnswer),
          file: null,
          timestamp: new Date().toLocaleTimeString('vi-VN', { hour: '2-digit', minute: '2-digit' }),
          createdAt: Date.now()
        };

        messages.push(botMessage);
        if (messages.length > 250) messages.shift();
        saveMessages();

        io.to('noel_autonomous_room').emit('bot_typing', { isTyping: false });
        io.to('noel_autonomous_room').emit('new_message', botMessage);
      } catch (e) {
        io.to('noel_autonomous_room').emit('bot_typing', { isTyping: false });
      }
    }
  });

  socket.on('delete_message', ({ messageId, adminToken }) => {
    if (!adminToken || !adminTokens.has(adminToken)) {
      return socket.emit('action_error', 'B?n kh?ng c? quy?n qu?n tr? vi?n!');
    }
    const index = messages.findIndex(m => m.id === messageId);
    if (index !== -1) {
      messages.splice(index, 1);
      saveMessages();
      io.to('noel_autonomous_room').emit('message_deleted', { messageId });
    }
  });

  socket.on('clear_chat', ({ adminToken }) => {
    if (!adminToken || !adminTokens.has(adminToken)) {
      return socket.emit('action_error', 'B?n kh?ng c? quy?n qu?n tr? vi?n!');
    }
    messages.length = 0;
    saveMessages();
    io.to('noel_autonomous_room').emit('chat_cleared', {
      by: currentUser ? currentUser.username : 'Admin'
    });
  });

  socket.on('disconnect', () => {
    if (currentUser) {
      onlineUsers.delete(socket.id);
      io.to('noel_autonomous_room').emit('user_left', {
        user: currentUser,
        onlineUsers: Array.from(onlineUsers.values())
      });
    }
  });
});

server.listen(PORT, '0.0.0.0', () => {
  console.log('Server is running on port ' + PORT);
});
